import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { NEXT_ORDER } from '../shop/cart-utils.js';

// Diwali 2026 sitewide pieces (announcement bar, logo ribbon) are copied into
// every hand-written page as well as generated by scripts/build-shop.js.
// These checks keep the 15 copies, the generator and the cart's offer dates
// in step. Remove with the campaign in the Nov 9 cleanup.

const HAND_PAGES = [
  '404.html', 'connect/index.html', 'enroll-adult/index.html', 'enroll/index.html',
  'faq/index.html', 'gallery/index.html', 'index.html', 'privacy-policy/index.html',
  'return-and-exchange-policy/index.html', 'services/3d-design/index.html',
  'services/on-demand/index.html', 'shipping-policy/index.html', 'shop/collage/index.html',
  'terms-of-service/index.html', 'workshop/index.html',
];
const GENERATED_PAGES = [
  'shop/index.html', 'shop/collections/diwali/index.html',
  'shop/products/layerweaver-e-gift-card/index.html', 'shop/account/index.html',
];

const read = p => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8');

// The bar block (comment, markup, inline date script), with hrefs blanked so
// pages at different depths compare equal.
function barBlock(html) {
  const m = html.match(/<!-- Announcement bar:[\s\S]*?<\/script>/g) || [];
  return m.map(b => b.replace(/href="[^"]*"/g, 'href=""').replace(/^[ \t]+/gm, ''));
}

describe('announcement bar copies', () => {
  const reference = barBlock(read('shop/index.html'))[0];

  it('is generated into the shop pages', () => {
    expect(reference).toBeTruthy();
  });

  it.each([...HAND_PAGES, ...GENERATED_PAGES])('%s has exactly one bar, the same as the generator\'s', page => {
    const blocks = barBlock(read(page));
    expect(blocks).toHaveLength(1);
    expect(blocks[0]).toBe(reference);
  });

  it.each([...HAND_PAGES, ...GENERATED_PAGES])('%s puts the bar before the header', page => {
    const html = read(page);
    expect(html.indexOf('class="announcement-bar"')).toBeLessThan(html.search(/<header[ >]/));
  });

  it('shows the next-order message on the offer dates the cart uses', () => {
    const next = reference.match(/<a href="" data-from="([\d-]+)" data-to="([\d-]+)"[^>]*>🪔/);
    expect(next).toBeTruthy();
    expect(next[1]).toBe(NEXT_ORDER.from);
    expect(next[2]).toBe(NEXT_ORDER.to);
  });

  it('keeps cart.js on the same offer dates as cart-utils.js', () => {
    const js = read('shop/cart.js');
    expect(js).toContain(`const NEXT_ORDER_FROM  = '${NEXT_ORDER.from}';`);
    expect(js).toContain(`const NEXT_ORDER_TO    = '${NEXT_ORDER.to}';`);
  });

  it('shows the gift card message till the day before Diwali', () => {
    expect(reference).toMatch(/<a href="" data-to="2026-11-07" hidden>🎁/);
  });

  it('links each message to where its call to action says', () => {
    const html = read('faq/index.html');
    expect(html).toMatch(/<a href="\/shop\/collections\/diwali\/" data-from="[^"]+" data-to="[^"]+" hidden>[^<]*<span class="announcement-cta">Shop Diwali →<\/span><\/a>/);
    expect(html).toMatch(/<a href="\/shop\/products\/layerweaver-e-gift-card\/" data-to="[^"]+" hidden>[^<]*<span class="announcement-cta">Gift cards →<\/span><\/a>/);
  });

  it('uses no em dashes', () => {
    expect(reference).not.toContain('—');
  });
});

describe('Diwali logo ribbon', () => {
  it.each([...HAND_PAGES, ...GENERATED_PAGES])('%s has one ribbon to the Diwali collection, outside the logo link', page => {
    const html = read(page);
    const ribbons = html.match(/<a href="[^"]*collections\/diwali\/" class="logo-diwali-ribbon">Shop Diwali Gifts 🪔<\/a>/g) || [];
    expect(ribbons).toHaveLength(1);
    // A link inside the logo link would be invalid HTML: the logo link must
    // close before the ribbon starts.
    const container = html.match(/<div class="logo-container">([\s\S]*?)<\/div>/)?.[1] || '';
    expect(container).toMatch(/class="logo-link">[\s\S]*?<\/a>\s*<a [^>]*class="logo-diwali-ribbon"/);
  });
});

describe('e-gift card in the Gifts menu', () => {
  it.each(GENERATED_PAGES.filter(p => p.includes('collections') || p === 'shop/index.html'))('%s lists it first in Gifts, on desktop and in the phone dropdown', page => {
    const html = read(page);
    const menu = html.match(/Gifts <i[^>]*><\/i>\s*<\/button>\s*<div class="collection-nav-menu">\s*(<a [^>]*>)/);
    expect(menu?.[1]).toMatch(/href="[^"]*products\/layerweaver-e-gift-card\/" class="collection-nav-menu-item collection-nav-menu-item--giftcard"/);
    const dropdown = html.match(/<div class="collection-dropdown-heading">Gifts<\/div>\s*(<a [^>]*>)/);
    expect(dropdown?.[1]).toMatch(/href="[^"]*products\/layerweaver-e-gift-card\/" class="collection-dropdown-item collection-dropdown-item--giftcard"/);
  });

  it('has no chip of its own in the strip', () => {
    expect(read('shop/index.html')).not.toContain('collection-nav-chip--giftcard');
  });
});
